function makeDuels(o){
const A="ABCDEFGHJKLMNPQRSTUVWXYZ23456789",D={},TG=[1,2,3],NC=6,ND=4,NEED=3;
const rid=n=>{let s="";for(let i=0;i<n;i++)s+=A[o.rand(32)];return s};
const cl=(x,n)=>String(x==null?"":x).replace(/[\u0000-\u001f\u007f<>]/g," ").trim().slice(0,n);
const err=(e,status)=>({e:e,status:status||400});
const get=id=>D[String(id||"").toUpperCase().replace(/[^A-Z0-9]/g,"")];
const who=(d,t)=>typeof t!=="string"?null:d.host.tok===t?"H":(d.guest&&d.guest.tok===t?"G":null);
const view=d=>({id:d.id,target:d.target,need:NEED,phase:d.phase,round:d.round,guesser:d.guesser,host:{name:d.host.name,av:d.host.av},guest:d.guest?{name:d.guest.name}:null,score:d.score,hasPick:d.pick!==null,got:d.got,last:d.last,winner:d.winner});
const push=d=>{d.upd=Date.now();o.emit(d.id,"snap",view(d))};
function create(b){const name=cl(b.name,20);if(name.length<2)return err("name");const t=TG.includes(+b.target)?+b.target:2;
let id;do{id=rid(6)}while(D[id]);
D[id]={id,target:t,phase:"wait",round:1,seq:0,guesser:"G",pick:null,got:[],last:null,winner:null,score:{H:0,G:0},host:{name,av:o.okAv(b.av)?b.av:null,tok:rid(20)},guest:null,upd:Date.now()};
return{id:id,token:D[id].host.tok,role:"H"}}
function join(b){const d=get(b.id);if(!d)return err("nf",404);const name=cl(b.name,20);if(name.length<2)return err("name");
if(d.guest)return err("full",409);d.guest={name,tok:rid(20)};d.phase="pick";push(d);return{id:d.id,token:d.guest.tok,role:"G"}}
function pick(b){const d=get(b.id);if(!d)return err("nf",404);const r=who(d,b.token);if(!r)return err("auth",403);
const c=Number(b.color);if(d.phase!=="pick"||r!==d.guesser||!Number.isInteger(c)||c<0||c>=NC)return err("turn",409);
d.pick=c;d.phase="roll";push(d);return{ok:1}}
function roll(b){const d=get(b.id);if(!d)return err("nf",404);const r=who(d,b.token);if(!r)return err("auth",403);
if(d.phase!=="roll"||r===d.guesser)return err("turn",409);
const dice=Array.from({length:ND},()=>1+o.rand(NC)),n=dice.filter(v=>v-1===d.pick).length,step=d.got.length+1;
let outcome="lost",auto=false;
if(n===ND){outcome="won";auto=true;d.got=Array(NEED).fill(d.pick)}
else if(n===1){d.got.push(d.pick);outcome=d.got.length>=NEED?"won":"next"}
if(outcome==="won"){d.score[d.guesser]++;if(d.score[d.guesser]>=d.target)d.winner=d.guesser}
d.seq++;d.last={seq:d.seq,round:d.round,guesser:d.guesser,color:d.pick,dice,n,hit:outcome!=="lost",step,outcome,auto,got:d.got.slice()};
d.phase="show";push(d);
setTimeout(()=>{if(!D[d.id])return;
if(d.winner)d.phase="done";
else if(outcome==="next"){d.pick=null;d.phase="pick"}
else{d.round++;d.guesser=d.guesser==="G"?"H":"G";d.got=[];d.pick=null;d.phase="pick"}
push(d)},5500);
return{ok:1}}
function snap(id){const d=get(id);return d?view(d):null}
function sweep(){const n=Date.now();for(const k in D)if(n-D[k].upd>3*36e5)delete D[k]}
return{create,join,pick,roll,snap,sweep}}
//#DUEL_END
